"""Launch move_group (and everything it needs) for the 3-joint 'arm' planning group.

Standalone launch file: does not depend on a colcon-built moveit_config package,
all URDF/SRDF/yaml files are loaded directly from this repo's directory tree.
"""

import os
import yaml

from launch import LaunchDescription
from launch_ros.actions import Node

THIS_DIR = os.path.dirname(os.path.abspath(__file__))
BASE_DIR = os.path.dirname(THIS_DIR)

OMPL_DEFAULTS_YAML = (
    "/opt/ros/jazzy/share/moveit_configs_utils/default_configs/ompl_defaults.yaml"
)


def load_file(path):
    with open(path, "r") as f:
        return f.read()


def load_yaml(path):
    with open(path, "r") as f:
        return yaml.safe_load(f)


def generate_launch_description():
    robot_description = {
        "robot_description": load_file(os.path.join(BASE_DIR, "urdf", "arm.urdf"))
    }
    robot_description_semantic = {
        "robot_description_semantic": load_file(
            os.path.join(BASE_DIR, "srdf", "arm.srdf")
        )
    }
    kinematics_yaml = load_yaml(os.path.join(BASE_DIR, "config", "kinematics.yaml"))
    robot_description_kinematics = {"robot_description_kinematics": kinematics_yaml}

    joint_limits_yaml = load_yaml(
        os.path.join(BASE_DIR, "config", "joint_limits.yaml")
    )
    robot_description_planning = {"robot_description_planning": joint_limits_yaml}

    ompl_yaml = load_yaml(os.path.join(BASE_DIR, "config", "ompl_planning.yaml"))
    ompl_defaults_yaml = load_yaml(OMPL_DEFAULTS_YAML)
    ompl_pipeline_config = dict(ompl_yaml)
    ompl_pipeline_config.update(ompl_defaults_yaml)

    planning_pipelines = {
        "planning_pipelines": ["ompl"],
        "default_planning_pipeline": "ompl",
        "ompl": ompl_pipeline_config,
    }

    moveit_controllers = load_yaml(
        os.path.join(BASE_DIR, "config", "moveit_controllers.yaml")
    )
    trajectory_execution = {
        "moveit_manage_controllers": True,
        "trajectory_execution.allowed_execution_duration_scaling": 1.2,
        "trajectory_execution.allowed_goal_duration_margin": 0.5,
        "trajectory_execution.allowed_start_tolerance": 0.01,
    }
    trajectory_execution.update(moveit_controllers)

    planning_scene_monitor_parameters = {
        "publish_planning_scene": True,
        "publish_geometry_updates": True,
        "publish_state_updates": True,
        "publish_transforms_updates": True,
    }

    move_group_node = Node(
        package="moveit_ros_move_group",
        executable="move_group",
        output="screen",
        parameters=[
            robot_description,
            robot_description_semantic,
            robot_description_kinematics,
            robot_description_planning,
            planning_pipelines,
            trajectory_execution,
            planning_scene_monitor_parameters,
            {"use_sim_time": False},
        ],
    )

    robot_state_publisher_node = Node(
        package="robot_state_publisher",
        executable="robot_state_publisher",
        output="screen",
        parameters=[robot_description, {"use_sim_time": False}],
    )

    joint_state_publisher_node = Node(
        package="joint_state_publisher",
        executable="joint_state_publisher",
        output="screen",
        parameters=[
            robot_description,
            {"use_sim_time": False, "rate": 30},
        ],
    )

    return LaunchDescription(
        [
            robot_state_publisher_node,
            joint_state_publisher_node,
            move_group_node,
        ]
    )

